package com.loopers.interfaces.consumer;import com.loopers.utils.DatabaseCleanUp;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import static org.assertj.core.api.Assertions.assertThat;@SpringBootTest class OrderConfirmedConsumerTest{@Autowired OrderConfirmedConsumer consumer;@Autowired DatabaseCleanUp cleanup;@AfterEach void clean(){cleanup.truncateAllTables();}@Test void sameEventDeliveryTwiceHasOneDurableEffect(){assertThat(consumer.handle("event-1","order-1")).isTrue();assertThat(consumer.handle("event-1","order-1")).isFalse();}}
